return $input.all().flatMap((item, index) => {
  const key = item.json.body?.data?.key;
  if (!key || key.fromMe) return [];
  const jid = [key.remoteJid, key.remoteJidAlt, key.senderPn].find(value =>
    typeof value === "string" && /^\d{10,15}@s\.whatsapp\.net$/.test(value));
  if (!jid || String(key.remoteJid).endsWith("@g.us")) return [];
  return [{ json: { numero: jid.split("@")[0] }, pairedItem: { item: index } }];
});

// Função para gerar uma string aleatória com letras maiúsculas e números
function gerarCodigo(tamanho) {
  const caracteres = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  let resultado = '';
  for (let i = 0; i < tamanho; i++) {
    const index = Math.floor(Math.random() * caracteres.length);
    resultado += caracteres[index];
  }
  return resultado;
}

// Retorna o código gerado no formato desejado
return [
  {
    json: {
      codigo: gerarCodigo(5),
    },
  },
];
